// ============ EDIT ME: your source feeds ============
// One line per RSS/Atom feed you want in the digest.
// These two are live examples so you can run the workflow as-is —
// replace them with the feeds you actually read.
const FEEDS = [
  'https://hnrss.org/frontpage',
  'https://www.theverge.com/rss/index.xml',
];
// =====================================================
return FEEDS.map((url) => ({ json: { url } }));

// Keep only the last 7 days, tidy the fields, cap at 25 stories.
const cutoff = Date.now() - 7 * 24 * 60 * 60 * 1000;
const seen = new Set();
const stories = [];

for (const item of $input.all()) {
  const j = item.json;
  const dateStr = j.isoDate ?? j.pubDate ?? null;
  const ts = dateStr ? Date.parse(dateStr) : NaN;
  if (Number.isNaN(ts) || ts < cutoff) continue;
  const link = j.link ?? '';
  if (!link || seen.has(link)) continue;
  seen.add(link);
  const snippet = (j.contentSnippet ?? j.content ?? '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 300);
  let source = '';
  try { source = new URL(link).hostname.replace(/^www\./, ''); } catch {}
  stories.push({ ts, title: j.title ?? '(untitled)', link, snippet, source });
}

stories.sort((a, b) => b.ts - a.ts);
if (stories.length === 0) {
  throw new Error('No stories in the last 7 days — check your feed URLs.');
}
return stories.slice(0, 25).map((s) => ({ json: s }));

// ============ EDIT ME: newsletter voice ============
const NEWSLETTER_NAME = 'My Weekly Digest';
const TONE = 'friendly, concise, no hype';
const MODEL = 'gpt-4o-mini'; // any chat model your API key can use
// ====================================================

const stories = $input.all().map((i) => i.json);
const list = stories
  .map((s, n) => `${n + 1}. [${s.source}] ${s.title}\n${s.snippet}\nLink: ${s.link}`)
  .join('\n\n');

const system = `You draft the weekly email digest for "${NEWSLETTER_NAME}". Tone: ${TONE}. You write tight, scannable email copy. You never invent facts beyond the provided stories, and every story keeps its link.`;

const user = `Draft this week's digest from the stories below.\n\nRules:\n- Group related stories into 3–5 themed sections with short <h2> headings.\n- Each story: 1–2 sentences in your own words + an <a href> "Read more" link.\n- Open with a 2-sentence intro of the week; close with one sign-off line.\n- Output CLEAN HTML ONLY (h2, p, a, ul/li). No <html>/<head>/<body> wrapper, no markdown, no code fences.\n\nSTORIES:\n\n${list}`;

return [{
  json: {
    body: {
      model: MODEL,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
      temperature: 0.4,
    },
  },
}];

// Wrap the AI copy in a minimal, email-safe shell.
let html = $input.first().json.choices?.[0]?.message?.content ?? '';
html = html.replace(/^```(html)?/m, '').replace(/```\s*$/m, '').trim();
if (!html) throw new Error('AI returned no content — check the previous node.');

const subject = `Your weekly digest — ${$now.toFormat('d LLLL')}`;
const content = `<div style="font-family:Georgia,serif;font-size:16px;line-height:1.6;color:#222;">${html}</div>`;

return [{
  json: {
    subject,
    preview_text: 'The week, in five minutes.',
    content,
  },
}];
